/* Minimal, dependency-free markdown renderer.
   Handles what notes actually contain: headings, fences, lists (incl. tasks),
   tables, quotes, images, links and Obsidian-style [[wikilinks]].          */

(function () {
  const ESC = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" };
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ESC[c]);

  const RE = {
    fence:   /^(\s*)(`{3,}|~{3,})\s*([\w+-]*)\s*$/,
    heading: /^(#{1,6})\s+(.*)$/,
    hr:      /^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/,
    quote:   /^\s*>\s?(.*)$/,
    li:      /^(\s*)(?:([-*+])|(\d+)[.)])\s+(.*)$/,
    task:    /^\[([ xX])\]\s+(.*)$/,
    tableSep:/^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$/,
  };

  // ---------------------------------------------------------------- inline
  function inline(src, opts) {
    // Code spans are pulled out first and replaced with a NUL-delimited
    // placeholder, so the emphasis and link passes cannot rewrite their
    // contents. NUL is used because it cannot appear in the source text.
    const codes = [];
    let s = String(src).replace(/`([^`\n]+)`/g, (_, c) => {
      codes.push(c);
      return "\u0000C" + (codes.length - 1) + "\u0000";
    });

    s = esc(s);

    // images before links, so ![]() does not become a plain link
    s = s.replace(/!\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g,
      (_, alt, src2) => `<img alt="${alt}" src="${opts.resolve(src2)}">`);

    // [[wikilink]] and [[wikilink|label]]
    s = s.replace(/\[\[([^\]\|#]+)(?:#[^\]\|]*)?(?:\|([^\]]+))?\]\]/g,
      (_, target, label) => {
        const t = target.trim();
        const hit = opts.wiki(t);
        return `<a class="wiki${hit ? "" : " dead"}" data-wiki="${esc(t)}">`
             + `${esc(label || t)}</a>`;
      });

    s = s.replace(/\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g,
      (_, text, href) => {
        const external = /^(https?:|mailto:)/.test(href);
        return external
          ? `<a href="${href}" target="_blank" rel="noreferrer">${text}</a>`
          : `<a class="wiki" data-rel="${esc(href)}">${text}</a>`;
      });

    s = s.replace(/(^|[\s(])(https?:\/\/[^\s<)]+)/g,
      (_, pre, url) => `${pre}<a href="${url}" target="_blank" rel="noreferrer">${url}</a>`);

    s = s.replace(/\*\*\*(\S(?:.*?\S)?)\*\*\*/g, "<strong><em>$1</em></strong>");
    s = s.replace(/\*\*(\S(?:.*?\S)?)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/(^|\W)_([^_\n]+)_(?=\W|$)/g, "$1<em>$2</em>");
    s = s.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, "$1<em>$2</em>");
    s = s.replace(/~~([^~\n]+)~~/g, "<del>$1</del>");
    s = s.replace(/==([^=\n]+)==/g, "<mark>$1</mark>");

    return s.replace(/\u0000C(\d+)\u0000/g,
                     (_, i) => `<code>${esc(codes[i])}</code>`);
  }

  // ----------------------------------------------------------------- block
  function render(src, options) {
    const opts = Object.assign(
      { wiki: () => false, resolve: (u) => u }, options || {});
    const lines = String(src).replace(/\r\n?/g, "\n").split("\n");
    const out = [];
    let i = 0;

    while (i < lines.length) {
      const line = lines[i];

      if (!line.trim()) { i++; continue; }

      let m = line.match(RE.fence);
      if (m) {
        const close = m[2][0];
        const lang = m[3] || "";
        const buf = [];
        i++;
        while (i < lines.length &&
               !(lines[i].trim().startsWith(close.repeat(3)) &&
                 !lines[i].trim().slice(3).trim())) {
          buf.push(lines[i]); i++;
        }
        i++;
        const code = buf.join("\n");
        const body = (window.HL && lang)
          ? window.HL.highlight(code, lang) : esc(code);
        out.push(`<pre><code class="lang-${esc(lang)}">${body}</code></pre>`);
        continue;
      }

      m = line.match(RE.heading);
      if (m) {
        const lvl = m[1].length;
        out.push(`<h${lvl}>${inline(m[2], opts)}</h${lvl}>`);
        i++; continue;
      }

      if (RE.hr.test(line)) { out.push("<hr>"); i++; continue; }

      if (RE.quote.test(line)) {
        const buf = [];
        while (i < lines.length && RE.quote.test(lines[i])) {
          buf.push(lines[i].match(RE.quote)[1]); i++;
        }
        out.push(`<blockquote>${render(buf.join("\n"), opts)}</blockquote>`);
        continue;
      }

      if (line.includes("|") && i + 1 < lines.length &&
          RE.tableSep.test(lines[i + 1])) {
        const rows = [];
        const cells = (l) => l.replace(/^\s*\|/, "").replace(/\|\s*$/, "")
                              .split("|").map((c) => c.trim());
        const head = cells(line);
        i += 2;
        while (i < lines.length && lines[i].includes("|") && lines[i].trim()) {
          rows.push(cells(lines[i])); i++;
        }
        // A `| | |` header row is legal markdown; don't render an empty band.
        const hasHead = head.some((c) => c.trim());
        out.push("<table>" +
          (hasHead ? "<thead><tr>" +
            head.map((c) => `<th>${inline(c, opts)}</th>`).join("") +
            "</tr></thead>" : "") + "<tbody>" +
          rows.map((r) => "<tr>" +
            r.map((c) => `<td>${inline(c, opts)}</td>`).join("") + "</tr>").join("") +
          "</tbody></table>");
        continue;
      }

      if (RE.li.test(line)) { i = list(lines, i, out, opts); continue; }

      const para = [];
      while (i < lines.length && lines[i].trim() &&
             !RE.heading.test(lines[i]) && !RE.hr.test(lines[i]) &&
             !RE.fence.test(lines[i]) && !RE.quote.test(lines[i]) &&
             !RE.li.test(lines[i])) {
        para.push(lines[i]); i++;
      }
      // Soft newlines reflow (CommonMark); a break is explicit only when the
      // author asked for one with two trailing spaces or a backslash. Files
      // out in the wild are hard-wrapped, and honouring every newline shreds
      // their prose mid-sentence.
      const flowed = inline(para.join("\n"), opts)
        .replace(/(?:  |\\)\n/g, "<br>")
        .replace(/\n/g, " ");
      out.push(`<p>${flowed}</p>`);
    }

    return out.join("\n");
  }

  /* Consume one list block (with nesting) starting at `start`. */
  function list(lines, start, out, opts) {
    const first = lines[start].match(RE.li);
    const baseIndent = first[1].length;
    const ordered = !!first[3];
    const items = [];
    let i = start;

    while (i < lines.length) {
      const m = lines[i] && lines[i].match(RE.li);
      if (!m) {
        // a blank line inside a list is fine if a list item follows
        if (lines[i] !== undefined && !lines[i].trim() &&
            lines[i + 1] && RE.li.test(lines[i + 1])) { i++; continue; }
        break;
      }
      const indent = m[1].length;
      if (indent < baseIndent) break;
      if (indent > baseIndent) {
        const sub = [];
        const subStart = i;
        while (i < lines.length && lines[i] && RE.li.test(lines[i]) &&
               lines[i].match(RE.li)[1].length > baseIndent) { sub.push(lines[i]); i++; }
        const inner = [];
        list(sub.map((l) => l.slice(baseIndent + 2)), 0, inner, opts);
        if (items.length) items[items.length - 1].sub = inner.join("");
        else i = subStart + sub.length;
        continue;
      }
      items.push({ text: m[4], sub: "" });
      i++;
    }

    const body = items.map((it) => {
      const t = it.text.match(RE.task);
      if (t) {
        const done = t[1].toLowerCase() === "x";
        return `<li class="task"><input type="checkbox" disabled${done ? " checked" : ""}>`
             + inline(t[2], opts) + it.sub + "</li>";
      }
      return `<li>${inline(it.text, opts)}${it.sub}</li>`;
    }).join("");

    out.push(ordered ? `<ol>${body}</ol>` : `<ul>${body}</ul>`);
    return i;
  }

  window.MD = { render, inline, esc };
})();

/home/dev/cortex/cortex/ui/style.css.text:
/* cortex — dark, quiet, gets out of the way of the graph */

:root{
  --bg:        #070910;
  --bg-2:      #0c111c;
  --line:      #1b2434;
  --line-2:    #2a374f;
  --fg:        #e6ebf4;
  --fg-dim:    #8996ad;
  --fg-faint:  #5c6880;
  --accent:    #4c8dff;
  --glass:     rgba(12,17,28,.78);

  --dir:     #f5a524;
  --note:    #34d399;
  --code:    #60a5fa;
  --config:  #a78bfa;
  --doc:     #f472b6;
  --media:   #fb7185;
  --archive: #94a3b8;
  --other:   #64748b;
  --tag:     #c084fc;

  --mono: ui-monospace, "JetBrains Mono", "SFMono-Regular", Menlo, Consolas, monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Inter, sans-serif;
}

*{box-sizing:border-box}
html,body{height:100%;margin:0;overflow:hidden;background:var(--bg);color:var(--fg);
  font:13.5px/1.55 var(--sans);-webkit-font-smoothing:antialiased}
button,input{font:inherit;color:inherit}
::selection{background:#2b5fd9aa}

#stage{position:fixed;inset:0;display:block;cursor:grab}
#stage.panning{cursor:grabbing}
#stage.overnode{cursor:pointer}

.glass{background:var(--glass);border:1px solid var(--line);border-radius:11px;
  backdrop-filter:blur(14px) saturate(140%)}

/* ---------------------------------------------------------------- top bar */
#bar{position:fixed;top:14px;left:14px;right:14px;z-index:10;display:flex;
  align-items:center;gap:10px;padding:8px 10px;background:var(--glass);
  border:1px solid var(--line);border-radius:13px;
  backdrop-filter:blur(16px) saturate(140%);
  box-shadow:0 10px 40px -18px #000}
.brand{display:flex;align-items:center;gap:8px;font-weight:700;letter-spacing:.13em;
  text-transform:uppercase;font-size:11px;color:var(--fg-dim);padding:0 6px 0 4px;
  white-space:nowrap}
.brand .dot{width:9px;height:9px;border-radius:50%;
  background:radial-gradient(circle at 35% 35%, #9ec5ff, var(--accent));
  box-shadow:0 0 12px #4c8dffcc}

/* the scope pill: shown only while the graph is narrowed to one folder */
.scope{display:flex;align-items:center;gap:8px;flex:none;max-width:240px;
  background:#12203a;border:1px solid #2c4a86;color:#bcd6ff;border-radius:9px;
  padding:7px 11px;cursor:pointer;font-size:12px;transition:.14s}
.scope:hover{background:#173055;border-color:#3d63ad}
/* an explicit display beats the UA [hidden] rule, so restore it by hand */
.scope[hidden]{display:none}
.scope #scope-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  font-weight:600}
.scope .x{opacity:.55;font-size:11px}
.scope:hover .x{opacity:1}

.searchwrap{position:relative;flex:0 1 380px;min-width:180px}
.searchwrap .mag{position:absolute;left:11px;top:50%;transform:translateY(-50%);
  width:15px;height:15px;fill:none;stroke:var(--fg-faint);stroke-width:2;
  stroke-linecap:round;pointer-events:none}
#q{width:100%;background:#0a0e17;border:1px solid var(--line);border-radius:9px;
  padding:8px 94px 8px 34px;outline:none;transition:border-color .15s, box-shadow .15s}
#q::placeholder{color:var(--fg-faint)}
#q:focus{border-color:var(--accent);box-shadow:0 0 0 3px #4c8dff22}
.slash{position:absolute;right:9px;top:50%;transform:translateY(-50%)}

/* names / text toggle, and the content-search results under the box */
.mode{position:absolute;right:32px;top:50%;transform:translateY(-50%);
  background:#101827;border:1px solid var(--line);border-radius:6px;
  padding:2px 8px;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;
  color:var(--fg-faint);cursor:pointer;transition:.14s}
.mode:hover{color:var(--fg);border-color:#31405c}
.mode.on{color:#bcd6ff;border-color:#2c4a86;background:#12203a}

#hits{position:absolute;top:calc(100% + 8px);left:0;width:min(620px,72vw);
  max-height:min(56vh,520px);overflow:auto;z-index:30;padding:5px;
  background:rgba(10,14,23,.97);border:1px solid var(--line);border-radius:11px;
  backdrop-filter:blur(16px) saturate(140%);box-shadow:0 22px 50px -22px #000}
#hits[hidden]{display:none}
#hits::-webkit-scrollbar{width:10px}
#hits::-webkit-scrollbar-thumb{background:#1c2740;border-radius:6px;
  border:3px solid transparent;background-clip:content-box}
.hit{display:flex;align-items:baseline;gap:12px;width:100%;padding:6px 9px;
  background:none;border:none;border-radius:7px;cursor:pointer;text-align:left;
  color:var(--fg-dim)}
.hit:hover{background:#182236;color:var(--fg)}
/* the keyboard's place in the list, which has to read as chosen rather than
   merely hovered, because both can be true at once */
.hit.on{background:#1c2c4c;color:var(--fg);box-shadow:inset 2px 0 0 var(--accent)}
.hit-name{flex:none;max-width:30ch;overflow:hidden;text-overflow:ellipsis;
  white-space:nowrap;font:12.5px var(--mono);color:var(--note)}
.hit-sub{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;
  white-space:nowrap;font:11.5px var(--mono);color:var(--fg-faint)}
/* a path identifies itself by its end, a line of prose by its start */
.hit-sub.path{text-align:right}
.hit:hover .hit-sub,.hit.on .hit-sub{color:var(--fg-dim)}
.hit-sub mark{background:#2b5fd955;color:#dce8ff;border-radius:3px;padding:0 1px}
.hits-note{padding:7px 10px;color:var(--fg-faint);font-size:12px}
.codeview .ln.hit-line{color:#ffd166;font-weight:700}

/* what git thinks of the selected file */
.chip.git{border-color:currentColor;opacity:.9;margin-right:auto}
.chip.git[hidden]{display:none}
#stat-git[hidden]{display:none}

kbd{background:#161f2e;border:1px solid #26324a;border-bottom-width:2px;
  border-radius:5px;padding:1px 6px;font:11px var(--mono);color:#b9c6dd}

#filters{display:flex;gap:5px;flex-wrap:nowrap;overflow:hidden}
.chip-f{display:flex;align-items:center;gap:6px;padding:5px 10px;border-radius:8px;
  border:1px solid transparent;background:#0e1524;color:var(--fg-faint);
  cursor:pointer;font-size:12px;white-space:nowrap;transition:.14s}
.chip-f:hover{color:var(--fg);background:#141d2f}
.chip-f.on{color:var(--fg);border-color:var(--line);background:#16203300}
.chip-f i{width:8px;height:8px;border-radius:50%;background:currentColor;flex:none}
.chip-f.off i{opacity:.25}
.chip-f.solo{border-color:currentColor;background:#16203a}

.spacer{flex:1}
button.ghost{background:#0e1524;border:1px solid var(--line);border-radius:9px;
  padding:7px 12px;cursor:pointer;color:var(--fg-dim);transition:.14s;white-space:nowrap}
button.ghost:hover{color:var(--fg);border-color:#31405c;background:#141d2f}
button.ghost.on{color:#bcd6ff;border-color:#2c4a86;background:#12203a}
button.ghost.sm{padding:3px 9px;font-size:11px}
button.primary{background:linear-gradient(180deg,#3d82ff,#2f6ee0);border:1px solid #4c8dff;
  border-radius:9px;padding:7px 13px;cursor:pointer;color:#fff;font-weight:600;
  box-shadow:0 6px 18px -8px #4c8dffcc;transition:.14s}
button.primary:hover{filter:brightness(1.12)}

/* --------------------------------------------------------------- sidebar */
#sidebar{position:fixed;top:0;left:0;bottom:0;width:260px;z-index:15;
  display:flex;flex-direction:column;background:rgba(9,13,22,.94);
  border-right:1px solid var(--line);backdrop-filter:blur(18px) saturate(140%);
  box-shadow:18px 0 50px -34px #000}
#sidebar[hidden]{display:none}

.sb-head{display:flex;align-items:center;justify-content:space-between;
  padding:14px 14px 10px;flex:none}
.sb-title{font-size:10px;letter-spacing:.16em;text-transform:uppercase;
  color:var(--fg-dim);font-weight:700}

#sb-filter{margin:0 14px 10px;flex:none;background:#0a0e17;color:var(--fg);
  border:1px solid var(--line);border-radius:8px;padding:6px 10px;outline:none;
  font-size:12px}
#sb-filter:focus{border-color:var(--accent);box-shadow:0 0 0 3px #4c8dff22}
#sb-filter::placeholder{color:var(--fg-faint)}

#sb-list{flex:1;overflow-y:auto;padding:0 8px 8px}
#sb-list::-webkit-scrollbar{width:9px}
#sb-list::-webkit-scrollbar-thumb{background:#1c2740;border-radius:6px;
  border:3px solid transparent;background-clip:content-box}

.sb-row{display:flex;align-items:center;gap:9px;width:100%;text-align:left;
  background:none;border:none;border-radius:8px;padding:7px 9px;cursor:pointer;
  color:var(--fg-dim);font-size:12.5px;transition:.12s}
.sb-row:hover{background:#141d2f;color:var(--fg)}
.sb-row.on{background:#12203a;color:#bcd6ff;font-weight:600}
.sb-row .bullet{width:8px;height:8px;border-radius:50%;background:var(--dir);
  flex:none}
.sb-row.all .bullet{background:var(--accent)}
.sb-row .nm{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sb-row .ct{font:10.5px var(--mono);color:var(--fg-faint);flex:none}
.sb-empty{color:var(--fg-faint);font-size:12px;padding:12px 9px}

.sb-foot{flex:none;padding:10px 14px 12px;border-top:1px solid var(--line);
  color:var(--fg-faint);font-size:10.5px;line-height:1.5}

button.ghost.icon{padding:7px 10px;font-size:13px;line-height:1;flex:none}

/* the top bar steps aside for the sidebar */
body.sidebar-open #bar{left:274px}
body.sidebar-open #stats{left:274px}

/* --------------------------------------------------------------- corners */
#stats{position:fixed;left:14px;bottom:14px;z-index:10;display:flex;align-items:center;
  gap:10px;padding:8px 13px;font-size:11.5px;color:var(--fg-dim)}
#stats .sep{width:1px;height:11px;background:var(--line)}
.muted{color:var(--fg-faint)}

#zoomer{position:fixed;right:14px;bottom:14px;z-index:10;display:flex;align-items:center;
  gap:4px;padding:4px}
#zoomer button{background:none;border:none;width:28px;height:28px;border-radius:7px;
  cursor:pointer;color:var(--fg-dim);font-size:16px;line-height:1}
#zoomer button:hover{background:#182236;color:var(--fg)}
#z-level{min-width:46px;text-align:center;font:11px var(--mono);color:var(--fg-faint)}

/* ---------------------------------------------------------------- reader */
#panel{position:fixed;top:0;right:0;bottom:0;width:520px;max-width:94vw;z-index:20;
  display:flex;flex-direction:column;background:rgba(8,12,20,.94);
  border-left:1px solid var(--line);backdrop-filter:blur(20px) saturate(140%);
  transform:translateX(102%);transition:transform .22s cubic-bezier(.4,0,.2,1);
  box-shadow:-24px 0 60px -30px #000}
#panel.open{transform:none}

#p-head{padding:16px 20px 14px;border-bottom:1px solid var(--line);flex:none}
#p-head .row{display:flex;align-items:center;justify-content:space-between;gap:10px}
.rowbtns{display:flex;gap:6px;flex:none}
.chip{font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:var(--fg-faint);
  border:1px solid var(--line);border-radius:20px;padding:3px 10px}
#p-name{font-size:19px;font-weight:650;margin:10px 0 6px;line-height:1.3;
  word-break:break-word}
#p-path{font:11px/1.5 var(--mono);color:var(--fg-faint);word-break:break-all;
  cursor:pointer}
#p-path:hover{color:var(--fg-dim)}
#p-meta{margin-top:9px;font-size:11.5px;color:var(--fg-faint)}

#p-acts{padding:13px 20px;display:flex;gap:7px;flex-wrap:wrap;flex:none;
  border-bottom:1px solid var(--line)}
#p-acts .more{position:relative}
#p-acts .menu{position:absolute;top:calc(100% + 6px);left:0;z-index:5;min-width:170px;
  background:#0d1320;border:1px solid var(--line);border-radius:10px;padding:5px;
  display:none;box-shadow:0 18px 40px -18px #000}
#p-acts .menu.open{display:block}
#p-acts .menu button{display:block;width:100%;text-align:left;background:none;
  border:none;padding:7px 10px;border-radius:7px;cursor:pointer;color:var(--fg-dim)}
#p-acts .menu button:hover{background:#182236;color:var(--fg)}

/* connections: what links to this file and what it links to, whether or not
   the other end has been grown into the graph yet */
#p-links{flex:none;border-bottom:1px solid var(--line);
  display:flex;flex-direction:column;min-height:0}
.conn-head{display:flex;align-items:center;gap:9px;width:100%;flex:none;
  padding:9px 20px;background:none;border:none;cursor:pointer;text-align:left;
  color:var(--fg-dim);font-size:12px}
.conn-head:hover{color:var(--fg);background:#0e1524}
.conn-head .caret{color:var(--fg-faint);font-size:10px;transition:transform .15s}
#p-links.closed .conn-head .caret{transform:rotate(-90deg)}
.conn-head .muted{margin-left:auto;color:var(--fg-faint);font-size:11px}
.conn-list{overflow:auto;max-height:138px;padding:0 12px 8px}
#p-links.closed .conn-list{display:none}
.conn-list::-webkit-scrollbar{width:10px}
.conn-list::-webkit-scrollbar-thumb{background:#1c2740;border-radius:6px;
  border:3px solid transparent;background-clip:content-box}
.conn{display:flex;align-items:baseline;gap:8px;width:100%;padding:5px 8px;
  background:none;border:none;border-radius:7px;cursor:pointer;text-align:left;
  color:var(--fg-dim);font-size:12.5px}
.conn:hover{background:#182236;color:var(--fg)}
.conn .arrow{flex:none;width:11px;font-size:11px;color:var(--fg-faint)}
.conn.note .nm{color:var(--note)}
.conn.code .nm{color:var(--code)}
.conn.tag .nm{color:var(--tag)}
.conn .nm{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:26ch}
.conn .where{margin-left:auto;flex:none;font:10.5px/1 var(--mono);
  color:var(--fg-faint);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  max-width:20ch}

#p-body{flex:1;min-height:0;overflow:auto;padding:18px 20px 60px}
#p-body::-webkit-scrollbar{width:10px}
#p-body::-webkit-scrollbar-thumb{background:#1c2740;border-radius:6px;
  border:3px solid transparent;background-clip:content-box}
#p-body::-webkit-scrollbar-thumb:hover{background:#2b3a5c;background-clip:content-box}

/* maximised reader: the panel takes the whole window, so a PDF or a long note
   gets real space instead of a 520px column.

   The chrome collapses to two thin rows. At full width you are here to read the
   file, not to admire its path, and a tall header was stealing a third of the
   screen from the document. */
#panel.max{width:100vw;max-width:100vw;border-left:none}

#panel.max #p-head{display:flex;align-items:center;gap:12px;padding:8px 18px;
  border-bottom:none}
#panel.max #p-kind,#panel.max #p-git{display:none}
#panel.max #p-name{order:1;flex:none;margin:0;font-size:14px;max-width:44ch;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#panel.max #p-path{order:2;flex:1 1 auto;min-width:0;margin:0;white-space:nowrap;
  overflow:hidden;text-overflow:ellipsis}
#panel.max #p-meta{order:3;flex:none;margin:0;white-space:nowrap}
#panel.max #p-head .row{order:4;flex:none}
#panel.max #p-acts{padding:0 18px 8px;border-bottom:none}
#panel.max #p-links{display:none}
#panel.max #p-acts button{padding:5px 11px}

/* Media fills whatever height is left. Measuring it with calc() meant guessing
   the header height, and guessing wrong put a second scrollbar on the panel. */
#panel.max #p-body{padding:0 18px 14px;min-height:0}
#panel.max #p-body.fill{padding:0;overflow:hidden;display:flex}
#panel.max #p-body.fill .viewer-frame{flex:1;height:auto;border:none;
  border-radius:0;border-top:1px solid var(--line)}
#panel.max #p-body.fill .viewer-img{max-height:100%;max-width:100%;margin:auto;
  border:none;border-radius:0}

/* keep prose at a readable measure even on a wide screen */
#panel.max .md{max-width:78ch;margin:0 auto}
#panel.max .codeview{max-width:120ch}

/* rendered markdown */
.md{font-size:14px;line-height:1.72;color:#d3dbe9}
.md h1,.md h2,.md h3,.md h4{color:#fff;line-height:1.3;margin:1.5em 0 .5em;font-weight:650}
.md h1{font-size:1.5em;border-bottom:1px solid var(--line);padding-bottom:.3em}
.md h2{font-size:1.28em;border-bottom:1px solid var(--line);padding-bottom:.25em}
.md h3{font-size:1.12em}
.md h1:first-child,.md h2:first-child{margin-top:0}
.md p{margin:.85em 0}
.md a{color:#7db1ff;text-decoration:none;border-bottom:1px solid #7db1ff40}
.md a:hover{border-bottom-color:#7db1ff}
.md a.wiki{color:var(--note);border-bottom-color:#34d39940;cursor:pointer}
.md a.wiki.dead{color:var(--fg-faint);border-bottom-style:dotted}
.md code{background:#141d2e;border:1px solid #1e2a40;border-radius:5px;
  padding:1px 5px;font:12.5px var(--mono);color:#e3b9ff}
.md pre{background:#0a0f1a;border:1px solid var(--line);border-radius:9px;
  padding:13px 15px;overflow-x:auto;margin:1em 0}
.md pre code{background:none;border:none;padding:0;color:#cbd5e1;font-size:12.5px;
  line-height:1.6}
.md blockquote{margin:1em 0;padding:.2em 0 .2em 15px;border-left:3px solid #2a3b5c;
  color:var(--fg-dim)}
.md ul,.md ol{padding-left:1.4em;margin:.8em 0}
.md li{margin:.3em 0}
.md li.task{list-style:none;margin-left:-1.2em}
.md li.task input{margin-right:8px;accent-color:var(--accent)}
.md hr{border:none;border-top:1px solid var(--line);margin:1.8em 0}
.md table{border-collapse:collapse;width:100%;margin:1em 0;font-size:13px;display:block;
  overflow-x:auto}
.md th,.md td{border:1px solid var(--line);padding:7px 11px;text-align:left}
.md th{background:#101827;font-weight:650;color:#fff}
.md img{max-width:100%;border-radius:8px}

/* code view */
.codeview{margin:0;font:12.5px/1.65 var(--mono);tab-size:4}
.codeview .ln{display:inline-block;width:3.2em;padding-right:1.1em;text-align:right;
  color:#39445c;user-select:none}
.tok-kw{color:#c792ea}.tok-str{color:#95e1a4}.tok-num{color:#ffb86c}
.tok-com{color:#4f5b75;font-style:italic}.tok-fn{color:#82aaff}
.tok-type{color:#ffcb6b}.tok-op{color:#89ddff}

/* other viewers */
.viewer-frame{width:100%;height:calc(100vh - 240px);border:1px solid var(--line);
  border-radius:9px;background:#0a0f1a}
.viewer-img{max-width:100%;border-radius:9px;border:1px solid var(--line);
  background:#0a0f1a}
.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:9px}
.tablewrap table{border-collapse:collapse;font:12px var(--mono);white-space:nowrap}
.tablewrap td,.tablewrap th{border-bottom:1px solid var(--line);
  border-right:1px solid var(--line);padding:6px 10px}
.tablewrap tr:first-child td{background:#101827;color:#fff;font-weight:650;
  position:sticky;top:0}
.empty{color:var(--fg-faint);font-size:12.5px;padding:8px 0}
.empty b{color:var(--fg-dim);font-weight:600}

/* --------------------------------------------------------------- overlays */
#toast{position:fixed;left:50%;bottom:26px;z-index:40;transform:translate(-50%,30px);
  opacity:0;pointer-events:none;padding:11px 20px;border-radius:10px;font-weight:600;
  font-size:12.5px;background:linear-gradient(180deg,#3d82ff,#2f6ee0);color:#fff;
  box-shadow:0 14px 40px -14px #4c8dff;transition:.2s cubic-bezier(.4,0,.2,1)}
#toast.show{opacity:1;transform:translate(-50%,0)}
#toast.warn{background:linear-gradient(180deg,#f5a524,#dc8a12);
  box-shadow:0 14px 40px -14px #f5a524}

.modal{position:fixed;inset:0;z-index:50;display:none;align-items:center;
  justify-content:center;background:#04060bcc;backdrop-filter:blur(4px)}
.modal.open{display:flex}
.sheet{max-width:520px;width:92vw;padding:26px 28px}
.sheet h2{margin:0 0 18px;font-size:15px;letter-spacing:.13em;text-transform:uppercase;
  color:var(--fg-dim)}
.sheet dl{display:grid;grid-template-columns:auto 1fr;gap:9px 16px;margin:0 0 20px;
  align-items:baseline}
.sheet dt{text-align:right}
.sheet dd{margin:0;color:var(--fg-dim);font-size:12.5px}
.sheet p{font-size:12.5px;line-height:1.65;margin:0 0 18px}
